        emon.Testport.AssertEq(Plan.AnArg(c, a1, 3), 300, "dpi");
        emon.Testport.AssertEq(Plan.AnStatus(c, a2), 1, "decode failed");
        emon.Testport.AssertEq(Plan.AnOk(c, a2), 0, "not ok");
        emon.Testport.AssertEq(Plan.RecLen(c, a2), 4, "a failure is the header and a status");
